import{d as g,C as n,o as h,c as u,a3 as i,E as a,j as t,a as d}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"论语·公冶长","description":"《论语》第 5 篇「公冶长」——二十八章原文与导读。孔子评点弟子与时人，闻一知十、听言观行、不耻下问、老者安之。","frontmatter":{"title":"论语·公冶长","description":"《论语》第 5 篇「公冶长」——二十八章原文与导读。孔子评点弟子与时人，闻一知十、听言观行、不耻下问、老者安之。","category":"guide","aliases":["公冶长","公冶长篇","公冶长第五","论语公冶长","lunyu 公冶长"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-05.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-05.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/lunyu/chapter-05.md"},x=g({...m,setup(y){const s=[{id:"yi",label:"一、子谓公冶长",showLabel:!0,sentences:[["子谓公冶长：“可妻也，虽在",{text:"缧绁",glossary:"leixie"},"之中，非其罪也！”以其子妻之。"]],note:"孔子论公冶长：「可妻也，虽在缧绁之中，非其罪也」——可以把女儿嫁给他；他虽曾身陷囹圄（缧绁＝拘系之绳索），但那不是他的罪过。于是把自己的女儿嫁给了他。"},{id:"er",label:"二、子谓南容",showLabel:!0,sentences:[["子谓南容：“邦有道不废；邦无道免于刑戮。”以其兄之子妻之。"]],note:"孔子论南容：「邦有道不废；邦无道免于刑戮」——国家有道时不被废弃，国家无道时能免于刑戮。于是把哥哥的女儿嫁给了他。与上章合观，孔子择婿皆以德。"},{id:"san",label:"三、君子哉若人",showLabel:!0,sentences:[["子谓子贱：“君子哉若人！鲁无君子者，斯焉取斯？”"]],note:"孔子评子贱：「君子哉若人！鲁无君子者，斯焉取斯」——这人真是个君子啊！倘若鲁国没有君子，他从哪里学来这样的德行？既赞子贱，亦赞鲁之多君子。"},{id:"si",label:"四、瑚琏之器",showLabel:!0,sentences:[["子贡问曰：“赐也何如？”子曰：“女器也。”曰：“何器也？”曰：“",{text:"瑚琏",glossary:"hulian"},"也。”"]],note:"子贡问：「赐也何如」——我怎么样？孔子说：「女（汝）器也」——你是个器。问「何器也」，答：「瑚琏也」——是宗庙中盛黍稷的贵重礼器。既许其贵重，亦暗含「器则各有所限」之意。"},{id:"wu",label:"五、焉用佞",showLabel:!0,sentences:[["或曰：“雍也仁而不",{text:"佞",glossary:"ning"},"。”子曰：“焉用佞？",{text:"御人以口给",glossary:"yurenyikouji"},"，屡憎于人。不知其仁，焉用佞？”"]],note:"有人说冉雍仁而不佞（无口才）。孔子说：「焉用佞？御人以口给，屡憎于人」——哪里用得着口才？靠口舌敏捷去应对人，常招人厌憎。「不知其仁，焉用佞」——我不知他是否仁，但何必要口才？"},{id:"liu",label:"六、吾斯之未能信",showLabel:!0,sentences:[["子使漆雕开仕。对曰：“吾斯之未能信。”子",{text:"说",glossary:"yue-xin"},"。"]],note:"孔子让漆雕开去做官。漆雕开答：「吾斯之未能信」——我对这个（做官之道）还没有自信。孔子很高兴（说＝悦）。喜其不自欺、不急于仕。"},{id:"qi",label:"七、乘桴浮于海",showLabel:!0,sentences:[["子曰：“道不行，乘",{text:"桴",glossary:"fu-fa"},"浮于海，从我者其由与？”子路闻之喜，子曰：“由也好勇过我，无所取材。”"]],note:"「道不行，乘桴浮于海，从我者其由与」——道行不通，便乘木筏浮于海上，跟从我的大概只有仲由吧？子路闻之而喜。孔子遂曰：「由也好勇过我，无所取材」——仲由好勇超过我，（可惜）无从取用其材（一说「材」同「裁」，谓不知裁度）。"},{id:"ba",label:"八、不知其仁也",showLabel:!0,sentences:[["孟武伯问：“子路仁乎？”子曰：“不知也。”又问，子曰：“由也，千乘之国，可使治其赋也，不知其仁也。”“求也何如？”子曰：“千室之邑、百乘之家，可使为之宰也，不知其仁也。”“赤也何如？”子曰：“",{text:"束带立于朝",glossary:"shudaierlichao"},"，可使与宾客言也，不知其仁也。”"]],note:"孟武伯问子路是否仁。孔子答「不知也」；再问，答：仲由嘛，千乘之国可让他管兵赋，至于仁，不知。问冉求，答：千室之邑、百乘之家，可让他做总管，至于仁，不知。问公西赤，答：束带立于朝，可使他与宾客应对，至于仁，不知。三答皆许其才而不敢许其仁。"},{id:"jiu",label:"九、闻一知十",showLabel:!0,sentences:[["子谓子贡曰：“女与回也孰愈？”对曰：“赐也何敢望回？回也闻一以知十，赐也闻一以知二。”子曰：“弗如也，吾与女弗如也！”"]],note:"孔子问子贡：「女（汝）与回也孰愈」——你和颜回谁强？子贡答：「赐也何敢望回？回也闻一以知十，赐也闻一以知二」——我怎敢比颜回？他闻一知十，我闻一知二。孔子说：「弗如也，吾与女弗如也」——是不如他；我与你都不如他。"},{id:"shi",label:"十、听其言而观其行",showLabel:!0,sentences:[["宰予昼寝。子曰：“朽木不可雕也，粪土之墙不可",{text:"杇",glossary:"wu-qiang"},"也，于予与何",{text:"诛",glossary:"zhu"},"？”子曰：“始吾于人也，听其言而信其行；今吾于人也，听其言而观其行。于予与改是。”"]],note:"宰予昼寝。孔子说：「朽木不可雕也，粪土之墙不可杇也」（杇＝粉刷），「于予与何诛」（对宰予还责备什么呢）。又说：「始吾于人也，听其言而信其行；今吾于人也，听其言而观其行。于予与改是」——起初我听其言便信其行，如今要听其言而观其行；是宰予使我改了这看法。"},{id:"shiyi",label:"十一、枨也欲，焉得刚",showLabel:!0,sentences:[["子曰：“吾未见刚者。”或对曰：“申枨。”子曰：“枨也欲，焉得刚？”"]],note:"「吾未见刚者」——我没见过刚强的人。有人答「申枨」。孔子说：「枨也欲，焉得刚」——申枨多欲，怎能算刚？言「刚」是理胜于欲，非血气之强。"},{id:"shier",label:"十二、非尔所及也",showLabel:!0,sentences:[["子贡曰：“我不欲人之加诸我也，吾亦欲无加诸人。”子曰：“赐也，非尔所及也。”"]],note:"子贡说：「我不欲人之加诸我也，吾亦欲无加诸人」——不愿别人加到我身上的，我也不想加到别人身上。孔子说：「赐也，非尔所及也」——赐啊，这不是你目前所能做到的。其义与「己所不欲，勿施于人」同，而孔子谓其难。"},{id:"shisan",label:"十三、言性与天道",showLabel:!0,sentences:[["子贡曰：“夫子之文章，可得而闻也；夫子之言性与天道，不可得而闻也。”"]],note:"子贡说：「夫子之文章，可得而闻也」——老师讲的诗书礼乐等可见之文，我们能听到；「夫子之言性与天道，不可得而闻也」——老师讲性与天道的话，却听不到。此章见孔子罕言性与天道。"},{id:"shisi",label:"十四、唯恐有闻",showLabel:!0,sentences:[["子路有闻，未之能行，唯恐有闻。"]],note:"「子路有闻，未之能行，唯恐有闻」——子路听到一个道理，尚未能实行，就唯恐再听到新的。写其笃行。"},{id:"shiwu",label:"十五、不耻下问",showLabel:!0,sentences:[["子贡问曰：“孔文子何以谓之文也？”子曰：“敏而好学，不耻下问，是以谓之文也。”"]],note:"子贡问：孔文子凭什么谥为「文」？孔子答：「敏而好学，不耻下问，是以谓之文也」——聪敏而好学，不以向地位在己下者请教为耻，因此谥为「文」。"},{id:"shiliu",label:"十六、子产有君子之道四",showLabel:!0,sentences:[["子谓子产：“有君子之道四焉：其行己也恭，其事上也敬，其养民也惠，其使民也义。”"]],note:"孔子评子产：「有君子之道四焉：其行己也恭，其事上也敬，其养民也惠，其使民也义」——自身行事恭敬，事奉上位恭敬，养民有恩惠，役使百姓合于义。"},{id:"shiqi",label:"十七、晏平仲善与人交",showLabel:!0,sentences:[["子曰：“晏平仲善与人交，久而敬之。”"]],note:"「晏平仲善与人交，久而敬之」——晏平仲善于与人交往，相交越久，人越敬重他。"},{id:"shiba",label:"十八、臧文仲居蔡",showLabel:!0,sentences:[["子曰：“臧文仲居蔡，山节藻棁，何如其知也？”"]],note:"「臧文仲居蔡，山节藻棁」——臧文仲为大龟（蔡＝大龟）盖屋，斗拱刻山、梁上短柱画藻（皆天子庙饰），「何如其知也」——这算什么明智？讥其僭越。"},{id:"shijiu",label:"十九、忠矣、清矣",showLabel:!0,sentences:[["子张问曰：“令尹子文三仕为令尹，无喜色，三已之无愠色，旧令尹之政必以告新令尹，何如？”子曰：“忠矣。”曰：“仁矣乎？”曰：“未知，焉得仁？”“崔子弑齐君，陈文子有马十乘，弃而违之。至于他邦，则曰：‘犹吾大夫崔子也。’违之。之一邦，则又曰：‘犹吾大夫崔子也。’违之。何如？”子曰：“清矣。”曰：“仁矣乎？”曰：“未知，焉得仁？”"]],note:"子张问：令尹子文三次为令尹而无喜色，三次被免而无愠色，且将旧政告于新令尹，如何？孔子答「忠矣」；再问「仁矣乎」，答「未知，焉得仁」。又问崔杼弑齐君，陈文子弃马十乘而去，至于他邦亦如此，孔子答「清矣」；再问仁，仍答「未知，焉得仁」。许其忠、许其清，而不许其仁。"},{id:"ershi",label:"二十、再，斯可矣",showLabel:!0,sentences:[["季文子三思而后行，子闻之曰：“再，斯可矣。”"]],note:"「季文子三思而后行」——季文子每事必三次思虑而后行。孔子闻之曰：「再，斯可矣」——想两次就可以了（一说讥其多虑）。"},{id:"ershiyi",label:"二十一、其知可及也",showLabel:!0,sentences:[["子曰：“宁武子，邦有道则知，邦无道则愚。其知可及也，其愚不可及也。”"]],note:"「宁武子，邦有道则知，邦无道则愚」——宁武子在国家有道时显得聪明，无道时显得愚钝。「其知可及也，其愚不可及也」——他那聪明别人赶得上，那「愚」别人赶不上。"},{id:"ershier",label:"二十二、归与！归与",showLabel:!0,sentences:[["子在陈，曰：“归与！归与！吾党之小子",{text:"狂简",glossary:"kuangjian"},"，",{text:"斐然成章",glossary:"feiranchengzhang"},"，不知所以裁之。”"]],note:"孔子在陈国，说：「归与！归与！吾党之小子狂简，斐然成章，不知所以裁之」——回去吧！回去吧！我乡里的学生们志向高远而行事粗略（狂简），文采斐然成章，却不知如何裁剪。"},{id:"ershisan",label:"二十三、不念旧恶",showLabel:!0,sentences:[["子曰：“伯夷、叔齐不念旧恶，怨是用",{text:"希",glossary:"xi"},"。”"]],note:"「伯夷、叔齐不念旧恶，怨是用希」——伯夷、叔齐不记旧怨，因此别人对他们的怨恨很少（希＝少）。"},{id:"ershisi",label:"二十四、孰谓微生高直",showLabel:!0,sentences:[["子曰：“孰谓微生高直？或乞",{text:"醯",glossary:"xi-cu"},"焉，乞诸其邻而与之。”"]],note:"「孰谓微生高直」——谁说微生高直？有人向他讨醋（醯＝醋），他自己没有，却向邻家讨来给人。此章讥其曲意徇物，非真直。"},{id:"ershiwu",label:"二十五、左丘明耻之",showLabel:!0,sentences:[["子曰：“巧言、令色、",{text:"足恭",glossary:"zugong"},"，左丘明耻之，丘亦耻之。",{text:"匿怨而友其人",glossary:"niyuaneryou"},"，左丘明耻之，丘亦耻之。”"]],note:"「巧言、令色、足恭」（足恭＝过分的恭敬），「左丘明耻之，丘亦耻之」；「匿怨而友其人」（藏起怨而与人交好），「左丘明耻之，丘亦耻之」。两事皆以为耻，见孔子之直。"},{id:"ershiliu",label:"二十六、老者安之",showLabel:!0,sentences:[["颜渊、季路侍。子曰：“盍各言尔志？”子路曰：“愿车马衣轻裘，与朋友共，敝之而无憾。”颜渊曰：“愿无",{text:"伐善",glossary:"fashan"},"，无",{text:"施劳",glossary:"shilao"},"。”子路曰：“愿闻子之志。”子曰：“",{text:"老者安之",glossary:"laozheanzhi"},"，朋友信之，少者怀之。”"]],note:"颜渊、季路侍侧。孔子说：「盍各言尔志」——何不各说其志？子路说：愿车马衣裘与朋友共用，用坏了也不怨。颜渊说：「愿无伐善，无施劳」——不夸耀自己的长处，不表白自己的功劳。子路问老师之志，孔子说：「老者安之，朋友信之，少者怀之」——使老者安适，使朋友信任，使少者得关怀。一章见三人胸襟。"},{id:"ershiqi",label:"二十七、内自讼",showLabel:!0,sentences:[["子曰：“已矣乎！吾未见能见其过而",{text:"内自讼",glossary:"neizisong"},"者也。”"]],note:"「已矣乎！吾未见能见其过而内自讼者也」——算了吧！我没见过能看见自己的过错而在内心自责的人（内自讼＝心中自讼其过）。"},{id:"ershiba",label:"二十八、不如丘之好学",showLabel:!0,sentences:[["子曰：“十室之邑，必有忠信如丘者焉，不如丘之好学也。”"]],note:"「十室之邑，必有忠信如丘者焉，不如丘之好学也」——十户人家的小地方，必有像我这样忠信的人，只是不如我这样好学。以「好学」自许，是孔子少见的自我评价。"}],r=[{id:"leixie",term:"缧绁",pinyin:"léi xiè",meaning:"捆绑犯人的绳索，引申为牢狱。公冶长曾蒙冤入狱。"},{id:"hulian",term:"瑚琏",pinyin:"hú liǎn",meaning:"宗庙中盛黍稷的贵重礼器。孔子说子贡是「器」，且是贵重的器——赞其才具，也隐含「尚未至于不器」之意。"},{id:"ning",term:"佞",pinyin:"nìng",meaning:"口才敏捷、能言善辩（此处偏贬义：巧嘴）。"},{id:"yurenyikouji",term:"御人以口给",pinyin:"yù rén yǐ kǒu jǐ",meaning:"用利嘴去顶撞、应对人。御：抵御、应对；口给：口才敏捷。"},{id:"yue-xin",term:"说",pinyin:"yuè",meaning:"同「悦」。孔子因漆雕开对出仕持慎重态度而高兴。"},{id:"fu-fa",term:"桴",pinyin:"fú",meaning:"木筏。乘桴浮于海：道不行则乘筏出海远去，是感慨之辞。"},{id:"shudaierlichao",term:"束带立于朝",pinyin:"shù dài lì yú cháo",meaning:"整束衣带、立于朝廷。指担任朝廷礼仪与外交应对之职。"},{id:"wu-qiang",term:"杇",pinyin:"wū",meaning:"抹墙的工具（此处作动词，粉刷）。粪土之墙不可杇：脏土筑的墙没法粉刷。"},{id:"zhu",term:"诛",pinyin:"zhū",meaning:"责备。于予与何诛：对宰予还能责备什么呢？"},{id:"kuangjian",term:"狂简",pinyin:"kuáng jiǎn",meaning:"志向高远而行事粗略。狂：志大；简：略。"},{id:"feiranchengzhang",term:"斐然成章",pinyin:"fěi rán chéng zhāng",meaning:"文采可观、有条理。斐然：有文采的样子。"},{id:"xi",term:"希",pinyin:"xī",meaning:"同「稀」，少。怨是用希：因此怨恨就少了。"},{id:"xi-cu",term:"醯",pinyin:"xī",meaning:"醋。"},{id:"zugong",term:"足恭",pinyin:"zú gōng",meaning:"过度恭敬、谄媚逢迎。足：过分（一说「足」为「巧」）。"},{id:"niyuaneryou",term:"匿怨而友其人",pinyin:"nì yuàn ér yǒu qí rén",meaning:"心里藏着怨恨，表面却和那人交好。匿：隐藏。"},{id:"fashan",term:"伐善",pinyin:"fá shàn",meaning:"夸耀自己的长处。伐：自夸。"},{id:"shilao",term:"施劳",pinyin:"shī láo",meaning:"表白自己的功劳。施：张扬、表白。"},{id:"laozheanzhi",term:"老者安之",pinyin:"lǎo zhě ān zhī",meaning:"使老人得到安适。此为孔子之志：老者安之，朋友信之，少者怀之。"},{id:"neizisong",term:"内自讼",pinyin:"nèi zì sòng",meaning:"在心里自我责备、自我争讼。讼：责备、争辩。"}];return(p,e)=>{const o=n("DaoTextReading"),l=n("DaoKeywordCards");return h(),u("div",null,[e[0]||(e[0]=i('<h1 id="论语·公冶长" tabindex="-1">论语·公冶长 <a class="header-anchor" href="#论语·公冶长" aria-label="Permalink to &quot;论语·公冶长&quot;">​</a></h1><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2><p>《公冶长》是《论语》里<strong>人物评点最多的一篇</strong>。孔子在这里逐一评说弟子与时人：公冶长、南容、子贱、子贡、冉雍、漆雕开、子路、冉求、公西赤；也评子产、晏平仲、臧文仲、令尹子文、陈文子、宁武子、伯夷叔齐、微生高。</p><p>但这一篇不只是点名册。它留下几句极重要的判断：<strong>「听其言而观其行」</strong>（因宰予昼寝而改）、<strong>「闻一以知十」</strong>（子贡自认不如颜回）、<strong>「不耻下问」</strong>（释孔文子之谥）、以及末两章的自我剖白——「未见能见其过而内自讼者也」「十室之邑，必有忠信如丘者焉，不如丘之好学也」。</p><p>尤其第二十六章，颜渊、子路各言其志，孔子最后说：「老者安之，朋友信之，少者怀之。」三句话，把孔子一生的志向说完了。</p><p>默认竹简沉浸通读；切「经典阅读」可点生词。</p>',6)),a(o,{colophon:"公冶长第五 · 二十八章",tone:"ink",sections:s,glossary:r,"default-mode":"slips","aria-label":"论语·公冶长 原文"}),e[1]||(e[1]=t("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[d("【原典层】注音与字词 "),t("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(l,{items:[{term:"缧绁",pinyin:["léi","xiè"],meaning:"捆绑犯人的绳索，引申为牢狱。公冶长曾蒙冤入狱。"},{term:"瑚琏",pinyin:["hú","liǎn"],meaning:"宗庙中盛黍稷的贵重礼器。孔子说子贡是「器」，且是贵重的器——赞其才具，也隐含「尚未至于不器」之意。"},{term:"佞",pinyin:["nìng"],meaning:"口才敏捷、能言善辩（此处偏贬义：巧嘴）。"},{term:"御人以口给",pinyin:["yù","rén","yǐ","kǒu","jǐ"],meaning:"用利嘴去顶撞、应对人。御：抵御、应对；口给：口才敏捷。"},{term:"说",pinyin:["yuè"],meaning:"同「悦」。孔子因漆雕开对出仕持慎重态度而高兴。"},{term:"桴",pinyin:["fú"],meaning:"木筏。乘桴浮于海：道不行则乘筏出海远去，是感慨之辞。"},{term:"束带立于朝",pinyin:["shù","dài","lì","yú","cháo"],meaning:"整束衣带、立于朝廷。指担任朝廷礼仪与外交应对之职。"},{term:"杇",pinyin:["wū"],meaning:"抹墙的工具（此处作动词，粉刷）。粪土之墙不可杇：脏土筑的墙没法粉刷。"},{term:"诛",pinyin:["zhū"],meaning:"责备。于予与何诛：对宰予还能责备什么呢？"},{term:"狂简",pinyin:["kuáng","jiǎn"],meaning:"志向高远而行事粗略。狂：志大；简：略。"},{term:"斐然成章",pinyin:["fěi","rán","chéng","zhāng"],meaning:"文采可观、有条理。斐然：有文采的样子。"},{term:"希",pinyin:["xī"],meaning:"同「稀」，少。怨是用希：因此怨恨就少了。"},{term:"醯",pinyin:["xī"],meaning:"醋。"},{term:"足恭",pinyin:["zú","gōng"],meaning:"过度恭敬、谄媚逢迎。足：过分（一说「足」为「巧」）。"},{term:"匿怨而友其人",pinyin:["nì","yuàn","ér","yǒu","qí","rén"],meaning:"心里藏着怨恨，表面却和那人交好。匿：隐藏。"},{term:"伐善",pinyin:["fá","shàn"],meaning:"夸耀自己的长处。伐：自夸。"},{term:"施劳",pinyin:["shī","láo"],meaning:"表白自己的功劳。施：张扬、表白。"},{term:"老者安之",pinyin:["lǎo","zhě","ān","zhī"],meaning:"使老人得到安适。此为孔子之志：老者安之，朋友信之，少者怀之。"},{term:"内自讼",pinyin:["nèi","zì","sòng"],meaning:"在心里自我责备、自我争讼。讼：责备、争辩。"}]}),e[2]||(e[2]=i('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《公冶长》二十八章，大半是<strong>孔子评人</strong>。他评弟子，也评时人；评的方式很有意思——<strong>不给一个笼统的总分，而是各说各的能与不能</strong>。子路可以治军赋，冉求可以做邑宰，公西赤可以办外交，但问到「仁」，孔子一律回答「不知其仁也」。这不是谦虚，是<strong>不肯轻易把「仁」这个字许给人</strong>。</p><p>这一篇还有两处是孔子在<strong>改自己</strong>。一是宰予昼寝之后，「听其言而观其行」——他承认自己以前看错了人的方法。二是漆雕开不愿出仕，他「说（悦）」——弟子不急于名利，他反倒高兴。</p><p>末两章是自我剖白：先说「未见能见其过而内自讼者」，再说「十室之邑必有忠信如丘者，不如丘之好学」——<strong>把忠信看作是许多人天生就有的，只把「好学」当作自己的长处。</strong></p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它教了一种更诚实的评价方式</strong>：孔子评人，先分清「能力」与「德性」。子路能治赋，但「不知其仁」——<strong>有本事不等于有德</strong>。这个分辨，用在今天的用人、看人上依然精准。</li><li><strong>它承认「人会看错」，并给出修正</strong>：「听其言而信其行」到「听其言而观其行」，这是孔子亲口承认的一次认知升级。<strong>判断人的方法要靠吃过的亏来校准。</strong></li><li><strong>它把「刚」讲得极深</strong>：别人说申枨刚强，孔子说「枨也欲，焉得刚」——<strong>欲望多的人，刚不起来。</strong> 一句话把「刚」从脾气拉到了欲望的层面。</li><li><strong>它给出「如何与人长久相处」的答案</strong>：「晏平仲善与人交，久而敬之」——<strong>关系越久越被敬重，这是很高明的处世。</strong> 反过来，常见的是越熟越随便、越久越轻慢。</li><li><strong>它把志向讲到极简</strong>：颜渊说不夸功，子路说愿与人共，孔子说老者安之、朋友信之、少者怀之。<strong>三句十五字，一个完整的社会理想。</strong></li><li><strong>它给出了「好学」的分量</strong>：忠信人人可得，好学却难得。孔子把这一点说成自己唯一的过人之处，值得细想。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>用人看两件事，别混为一谈</strong>：「可使治其赋」与「不知其仁」——能力与德性分开评。<strong>能干的人未必可托付，这两件事要分开打分。</strong></li><li><strong>判断人，拉长观察窗口</strong>：「听其言而观其行」——<strong>不因为一次漂亮的话就下结论，也不因为一次失误就否掉一个人。</strong></li><li><strong>问自己「欲望多不多」</strong>：想要的东西太多、被牵着走，就不容易「刚」。<strong>刚不是脾气硬，是不被欲望牵。</strong></li><li><strong>经营久的关系要留一份敬</strong>：「久而敬之」——越熟的人越要留分寸。<strong>亲近与尊重不冲突，越亲近越要维护尊重。</strong></li><li><strong>把「好学」当自己的长线优势</strong>：忠信可以天生，好学只能自己养。<strong>在做事的人里，长期保持好奇与更新的人极少。</strong></li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《公冶长》很像一份人物档案。孔子在这里点评了一大串人——他的学生、当时的执政者、隐士与贤人。有意思的是，他从不给一个笼统的好坏。他会说：这个人能做这件事，那个人能做那件事；至于仁不仁，那要另说。</p><p>这一篇最有生命力的两句话，反而是孔子在说自己「不了」的时候。一是看到宰予白天睡觉之后，他改了看人的方法——<strong>从前听他说什么就信他做什么，现在听他说什么，还要看他做什么。</strong> 二是他说自己没什么过人之处，忠信的人到处都是，他只不过比人家<strong>好学</strong>罢了。</p><p>至于志向，他讲得最简：<strong>让老人安心，让朋友信得过，让年轻人被照顾好。</strong></p><p>做到这三句，已经很了不起了。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>孔子评人从来不说「总分」，只分开说能力与德性。我在评价同事、家人时，是不是常常把「他能干」和「他可靠」混在一起？</li><li>「枨也欲，焉得刚」——我心里最放不下的那个「欲」是什么？它让我在哪件事上硬不起来？</li><li>「久而敬之」——我身边有哪些关系是「越久越敬重」，有哪些是「越熟越轻慢」？差别出在哪里？</li><li>「老者安之，朋友信之，少者怀之」——如果只准我留下三句自己的志向，会是什么？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-04">论语·里仁</a>　下篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-06">论语·雍也</a></li><li>参考：《论语》朱熹《四书章句集注·论语集注》；杨伯峻《论语译注》</li></ul>',21))])}}});export{c as __pageData,x as default};
